men=men[:m.start()]+'  function renderCombined(){\n    const root=document.getElementById(\'combinedRankingRoot\'),status=document.getElementById(\'combinedStatus\');if(!root||!status||!projection)return;\n    if(!projection.hasAny){status.textContent=\'\';root.innerHTML=\'<div class="avc-combined-empty">조별리그 첫 경기 결과가 등록되면 현재 예선 종합순위를 표시합니다.</div>\';return}\n    status.textContent=projection.poolComplete?\'조별리그 종료 · 예선 종합순위 확정\':`${projection.completedCount}/18경기 완료 기준 · 현재 예상`;\n    const desktop=projection.qualifiers.map(r=>`<div class="avc-combined-row ${r.team===\'대한민국\'?\'is-korea\':\'\'}"><span class="avc-combined-seed">${r.seed}번 시드</span>${standingFlag(r.team)}<strong>${esc(r.team)}</strong><span>${esc(r.pool)}조 ${r.poolPosition}위</span><span>${r.wins}승 · ${r.matchPoints}점</span><span>세트율 ${fmtRatio(r.setsFor,r.setsAgainst)}</span></div>`).join(\'\');\n    const rows=projection.combinedAll||[];\n    const complete=projection.poolComplete;\n    const opponentSeed=seed=>({1:8,8:1,4:5,5:4,2:7,7:2,3:6,6:3})[seed]||\'\';\n    const resultCell=r=>r.seed?`<span class="kvl-men-combined-result"><b>8강 진출</b><small>${r.seed}-${opponentSeed(r.seed)}</small></span>`:`<span class="kvl-men-combined-result is-out"><b>조별리그 탈락</b></span>`;\n    const head=complete\n      ? \'<span>종합순위</span><span>국기</span><span>국가</span><span>결과</span><span>승리 경기수</span><span>승점</span><span>세트 득실률</span><span>득점 득실률</span><span>조순위</span>\'\n      : \'<span>종합순위</span><span>국기</span><span>국가</span><span>조순위</span><span>승리 경기수</span><span>승점</span><span>세트 득실률</span><span>득점 득실률</span>\';\n    const body=rows.map(r=>{\n      const common=`<span class="kvl-men-combined-rank">${r.combinedRank}위</span>${standingFlag(r.team)}<strong class="kvl-men-combined-team">${esc(r.team)}</strong>`;\n      const stats=`<span class="kvl-men-combined-stat">${r.wins}승</span><span class="kvl-men-combined-stat">${r.matchPoints}</span><span class="kvl-men-combined-stat">${fmtRatio(r.setsFor,r.setsAgainst)}</span><span class="kvl-men-combined-stat">${r.pointMatches?fmtRatio(r.pointsFor,r.pointsAgainst):\'-\'}</span>`;\n      return complete\n        ? `<div class="kvl-men-combined-line ${r.team===\'대한민국\'?\'is-korea\':\'\'}">${common}${resultCell(r)}${stats}<span class="kvl-men-combined-stat">${esc(r.pool)}조 ${r.poolPosition}위</span></div>`\n        : `<div class="kvl-men-combined-line ${r.team===\'대한민국\'?\'is-korea\':\'\'}">${common}<span class="kvl-men-combined-stat">${esc(r.pool)}조 ${r.poolPosition}위</span>${stats}</div>`;\n    }).join(\'\');\n    root.innerHTML=`<div class="kvl-men-combined-desktop">${desktop}</div><div class="kvl-men-combined-mobile"><div class="kvl-men-combined-table ${complete?\'is-complete\':\'is-live\'}"><div class="kvl-men-combined-line is-head">${head}</div>${body}</div></div>`;\n  }\n\n'+'  const bracketTeam='+men[m.end():]
